insert into public.panda_records(kind,id,data) values('programs','studio_two_day_start','{"id":"studio_two_day_start","name":"Two-Day Full-Body Start","name_ar":"بداية الجسم الكامل · يومان","weeks":8,"status":"draft","version":1,"versions":[],"origin":"Panda coach template · 2026-09-14","goal":"Two manageable gym sessions to practise the main movement patterns.","description":"Two manageable gym sessions to practise the main movement patterns.","description_ar":"جلستان عمليتان في النادي للتدرب على أنماط الحركة الأساسية.","notes":"Coach template for healthy adults. Review experience, equipment, symptoms and schedule before publishing. Warm up, then use 1–3 lighter rehearsal sets for the first main lift; these are not working sets. When every set reaches the top of its rep range at the prescribed RIR on two sessions, use the smallest practical load increase and return to the lower end. Keep a rest day between full-body sessions. Reassess fatigue weekly; reduce working sets during a difficult week instead of adding failure work. Stop for pain or unusual symptoms and obtain appropriate advice.","notes_ar":"قالب للمدرب للبالغين الأصحاء. راجع الخبرة والمعدات والأعراض والجدول قبل النشر. قم بالإحماء ثم نفّذ 1–3 مجموعات تمهيدية أخف لأول رفعة أساسية؛ لا تُعد مجموعات عمل. عند بلوغ الحد الأعلى للتكرارات في كل المجموعات وبالجهد المحدد في جلستين، استخدم أصغر زيادة عملية في الحمل وعد إلى الحد الأدنى. اترك يوم راحة بين جلسات الجسم الكامل. راجع التعب أسبوعياً وقلل مجموعات العمل في الأسبوع الصعب بدلاً من إضافة عمل حتى العجز. توقف عند الألم أو الأعراض غير المعتادة واطلب المشورة المناسبة.","sessions":[{"id":"session_1","name":"Full body A · Learn the setup","name_ar":"الجسم الكامل أ · تعلّم الإعداد","day":"Monday","focus":"Press, row and legs","focus_ar":"دفع وسحب وساقان","image":"assets/equipment.webp","exercises":[{"exercise_id":"sheet_f860b6ddc424","sets":2,"reps":"8–12","rest":90,"load":"Choose a load that matches the assigned RIR.","tempo":"Controlled lowering; steady lift.","note