insert into public.panda_records(kind,id,data) values('programs','studio_upper_lower_growth','{"id":"studio_upper_lower_growth","name":"Upper / Lower Muscle Builder","name_ar":"بناء العضلات · علوي وسفلي","weeks":10,"status":"draft","version":1,"versions":[],"origin":"Panda coach template · 2026-09-14","goal":"Four sessions for experienced trainees who can recover between two upper and two lower days.","description":"Four sessions for experienced trainees who can recover between two upper and two lower days.","description_ar":"أربع جلسات للمتدربين ذوي الخبرة مع تعافٍ بين يومين علويين ويومين سفليين.","notes":"Coach template for healthy adults. Review experience, equipment, symptoms and schedule before publishing. Warm up, then use 1–3 lighter rehearsal sets for the first main lift; these are not working sets. When every set reaches the top of its rep range at the prescribed RIR on two sessions, use the smallest practical load increase and return to the lower end. Keep a rest day between full-body sessions. Reassess fatigue weekly; reduce working sets during a difficult week instead of adding failure work. Stop for pain or unusual symptoms and obtain appropriate advice.","notes_ar":"قالب للمدرب للبالغين الأصحاء. راجع الخبرة والمعدات والأعراض والجدول قبل النشر. قم بالإحماء ثم نفّذ 1–3 مجموعات تمهيدية أخف لأول رفعة أساسية؛ لا تُعد مجموعات عمل. عند بلوغ الحد الأعلى للتكرارات في كل المجموعات وبالجهد المحدد في جلستين، استخدم أصغر زيادة عملية في الحمل وعد إلى الحد الأدنى. اترك يوم راحة بين جلسات الجسم الكامل. راجع التعب أسبوعياً وقلل مجموعات العمل في الأسبوع الصعب بدلاً من إضافة عمل حتى العجز. توقف عند الألم أو الأعراض غير المعتادة واطلب المشورة المناسبة.","sessions":[{"id":"session_1","name":"Upper A · Horizontal focus","name_ar":"علوي أ · تركيز أفقي","day":"Monday","focus":"Chest and back with supporting arm work","focus_ar":"صدر وظهر مع عمل مساعد للذراعين","image":"assets/equipment.webp","exercises":[{"exercise_id":"ex_74bf403c1950","sets":3,"reps":"8–12","rest":120,"load