insert into public.panda_records(kind,id,data) values('programs','studio_strength_four','{"id":"studio_strength_four","name":"Four-Day Strength Practice","name_ar":"ممارسة القوة · أربعة أيام","weeks":8,"status":"draft","version":1,"versions":[],"origin":"Panda coach template · 2026-09-14","goal":"A lower-repetition template for lifters already confident with barbell technique.","description":"A lower-repetition template for lifters already confident with barbell technique.","description_ar":"قالب بتكرارات أقل لمن يتقنون بالفعل تقنية البار.","notes":"Coach template for healthy adults. Review experience, equipment, symptoms and schedule before publishing. Warm up, then use 1–3 lighter rehearsal sets for the first main lift; these are not working sets. When every set reaches the top of its rep range at the prescribed RIR on two sessions, use the smallest practical load increase and return to the lower end. Keep a rest day between full-body sessions. Reassess fatigue weekly; reduce working sets during a difficult week instead of adding failure work. Stop for pain or unusual symptoms and obtain appropriate advice.","notes_ar":"قالب للمدرب للبالغين الأصحاء. راجع الخبرة والمعدات والأعراض والجدول قبل النشر. قم بالإحماء ثم نفّذ 1–3 مجموعات تمهيدية أخف لأول رفعة أساسية؛ لا تُعد مجموعات عمل. عند بلوغ الحد الأعلى للتكرارات في كل المجموعات وبالجهد المحدد في جلستين، استخدم أصغر زيادة عملية في الحمل وعد إلى الحد الأدنى. اترك يوم راحة بين جلسات الجسم الكامل. راجع التعب أسبوعياً وقلل مجموعات العمل في الأسبوع الصعب بدلاً من إضافة عمل حتى العجز. توقف عند الألم أو الأعراض غير المعتادة واطلب المشورة المناسبة.","sessions":[{"id":"session_1","name":"Strength upper A","name_ar":"القوة · علوي أ","day":"Monday","focus":"Main press and supported pulling","focus_ar":"دفع أساسي وسحب متحكم به","image":"assets/equipment.webp","exercises":[{"exercise_id":"ex_0b0f76e0ce35","sets":3,"reps":"4–6","rest":180,"load":"Choose a load that matches the assigned RIR.","tempo":"Controlled lowering; steady lif