insert into public.panda_records(kind,id,data) values('programs','studio_busy_week','{"id":"studio_busy_week","name":"Busy-Week Two-Day Essentials","name_ar":"أساسيات الأسبوع المزدحم · يومان","weeks":6,"status":"draft","version":1,"versions":[],"origin":"Panda coach template · 2026-09-14","goal":"A compact maintenance-oriented routine with four exercises per session.","description":"A compact maintenance-oriented routine with four exercises per session.","description_ar":"روتين موجز يركز على الحفاظ على المستوى بأربعة تمارين لكل جلسة.","notes":"Coach template for healthy adults. Review experience, equipment, symptoms and schedule before publishing. Warm up, then use 1–3 lighter rehearsal sets for the first main lift; these are not working sets. When every set reaches the top of its rep range at the prescribed RIR on two sessions, use the smallest practical load increase and return to the lower end. Keep a rest day between full-body sessions. Reassess fatigue weekly; reduce working sets during a difficult week instead of adding failure work. Stop for pain or unusual symptoms and obtain appropriate advice.","notes_ar":"قالب للمدرب للبالغين الأصحاء. راجع الخبرة والمعدات والأعراض والجدول قبل النشر. قم بالإحماء ثم نفّذ 1–3 مجموعات تمهيدية أخف لأول رفعة أساسية؛ لا تُعد مجموعات عمل. عند بلوغ الحد الأعلى للتكرارات في كل المجموعات وبالجهد المحدد في جلستين، استخدم أصغر زيادة عملية في الحمل وعد إلى الحد الأدنى. اترك يوم راحة بين جلسات الجسم الكامل. راجع التعب أسبوعياً وقلل مجموعات العمل في الأسبوع الصعب بدلاً من إضافة عمل حتى العجز. توقف عند الألم أو الأعراض غير المعتادة واطلب المشورة المناسبة.","sessions":[{"id":"session_1","name":"Essentials A","name_ar":"الأساسيات أ","day":"Tuesday","focus":"Legs, push, pull and trunk","focus_ar":"ساقان ودفع وسحب وجذع","image":"assets/equipment.webp","exercises":[{"exercise_id":"sheet_f860b6ddc424","sets":2,"reps":"8–12","rest":90,"load":"Choose a load that matches the assigned RIR.","tempo":"Controlled lowering; steady lift.","notes":"Keep 