insert into public.panda_records(kind,id,data) values('nutrition_plans','studio_nutrition_mediterranean','{"id":"studio_nutrition_mediterranean","name":"Mediterranean-Inspired Week","name_ar":"أسبوع مستوحى من المتوسط","status":"draft","version":1,"versions":[],"origin":"Panda Kitchen coach template · 2026-09-14","description":"Vegetables, grains, pulses, fish and poultry in practical dishes.","description_ar":"خضروات وحبوب وبقول وأسماك ودواجن في أطباق عملية.","notes":"Vegetables, grains, pulses, fish and poultry in practical dishes. Template portions and the 2.5 L fluid placeholder require individual review. Targets initially match Menu 1; Menu 2 has its own calculated totals. Check allergies, preparation state and product labels. Adjust servings, targets and timing before publishing. Recipe amounts are estimates, not a clinical prescription.","notes_ar":"خضروات وحبوب وبقول وأسماك ودواجن في أطباق عملية. تحتاج حصص القالب والقيمة الأولية للسوائل 2.5 لتر إلى مراجعة فردية. تطابق الأهداف القائمة الأولى مبدئياً، وللقائمة الثانية إجمالياتها المحسوبة. راجع الحساسية وحالة التحضير وملصقات المنتجات. عدّل الحصص والأهداف والتوقيت قبل النشر. الكميات تقديرية وليست وصفة سريرية.","targets":{"protein":146.2,"carbs":187.8,"fat":82.7,"fiber":42.1,"calories":2080,"water":2.5},"variants":[{"id":"day-1","name":"Menu 1","meals":[{"id":"meal_7","name":"Shakshuka with wholegrain pita","name_ar":"شكشوكة مع خبز الحبوب الكاملة","time":"07:30","instructions":"Soften diced onion and pepper in the oil for 5 minutes. Add passata and spices; simmer for 8 minutes.\n\nMake two wells, add the eggs and cover. Cook gently until whites and yolks are firm.\n\nWarm the pita and serve alongside the skillet.","instructions_ar":"لين البصل والفلفل بالزيت ٥ دقائق ثم أضف الطماطم والبهارات واطه ٨ دقائق.\n\nاصنع فجوتين وأضف البيض وغط المقلاة حتى يتماسك البياض والصفار.\n\nسخن الخبز وقدمه بجانب الشكشوكة.","items":[{"food_id":"ingredient_egg","quantity":125.0},{"food_id":"ingredient_passata","quantity":250.0},{"food_i