insert into public.panda_records(kind,id,data) values('nutrition_plans','studio_nutrition_vegetarian','{"id":"studio_nutrition_vegetarian","name":"Vegetarian Everyday Fuel","name_ar":"غذاء نباتي يومي","status":"draft","version":1,"versions":[],"origin":"Panda Kitchen coach template · 2026-09-14","description":"Meat-free meals using dairy, eggs, tofu and pulses; this is not a vegan plan.","description_ar":"وجبات دون لحوم تستخدم الألبان والبيض والتوفو والبقول؛ ليست خطة نباتية صرفة.","notes":"Meat-free meals using dairy, eggs, tofu and pulses; this is not a vegan plan. Template portions and the 2.5 L fluid placeholder require individual review. Targets initially match Menu 1; Menu 2 has its own calculated totals. Check allergies, preparation state and product labels. Adjust servings, targets and timing before publishing. Recipe amounts are estimates, not a clinical prescription.","notes_ar":"وجبات دون لحوم تستخدم الألبان والبيض والتوفو والبقول؛ ليست خطة نباتية صرفة. تحتاج حصص القالب والقيمة الأولية للسوائل 2.5 لتر إلى مراجعة فردية. تطابق الأهداف القائمة الأولى مبدئياً، وللقائمة الثانية إجمالياتها المحسوبة. راجع الحساسية وحالة التحضير وملصقات المنتجات. عدّل الحصص والأهداف والتوقيت قبل النشر. الكميات تقديرية وليست وصفة سريرية.","targets":{"protein":161.5,"carbs":243.6,"fat":77.5,"fiber":68.7,"calories":2318,"water":2.5},"variants":[{"id":"day-1","name":"Menu 1","meals":[{"id":"meal_2","name":"Banana oat protein pancakes","name_ar":"بان كيك الشوفان والموز","time":"07:30","instructions":"Blend the oats, half the banana and eggs to form a thick batter.\n\nBrush a non-stick pan with the measured oil. Cook small pancakes over medium-low heat for 2–3 minutes per side, until set.\n\nServe with the yogurt and remaining sliced banana.","instructions_ar":"اخلط الشوفان ونصف الموز والبيض للحصول على عجينة سميكة.\n\nادهن مقلاة غير لاصقة بالزيت المحدد واطه أقراصاً صغيرة ٢–٣ دقائق لكل جانب حتى تنضج.\n\nقدمها مع الزبادي وبقية شرائح الموز.","items":[{"food_id":"ingredient_oats","quantity":62.5},{"food_id":"ingredient_banana","quantity":125.0},{"food_id":"ingredient_egg","quantity":125.0},{"food_id":"ingredient_yogurt","quantity":125.0},{"food_id":"ingredient_oil","quantity":3.75}],"image":"assets/recipes/02.webp","recipe_snapshot":{"id":"recipe_02","name":"Banana oat protein pancakes","name_ar":"بان كيك الشوفان والموز","category":"Breakfast","minutes":20,"wait_minutes":0,"servings":1,"summary":"A simple start, with clear portions and everyday ingredients.","summary_ar":"بداية بسيطة بمقادير واضحة ومكونات يومية.","ingredients":[{"id":"oats","name":"Rolled oats · dry","name_ar":"شوفان ملفوف · جاف","protein":13,"carbs":60,"fat":7,"fiber":10,"allergens":"Gluten","unit":"g","quantity":50},{"id":"banana","name":"Banana · peeled","name_ar":"موز مقشر","protein":1.1,"carbs":20,"fat":0.3,"fiber":2.6,"allergens":"","unit":"g","quantity":100},{"id":"egg","name":"Whole egg · shell removed","name_ar":"بيض كامل دون القشرة","protein":12.6,"carbs":0.7,"fat":9.5,"fiber":0,"allergens":"Egg","unit":"g","quantity":100},{"id":"yogurt","name":"Greek yogurt · plain, 0% fat","name_ar":"زبادي يوناني سادة خالي الدسم","protein":10,"carbs":4,"fat":0.4,"fiber":0,"allergens":"Milk","unit":"g","quantity":100},{"id":"oil","name":"Olive oil","name_ar":"زيت زيتون","protein":0,"carbs":0,"fat":100,"fiber":0,"allergens":"","unit":"g","quantity":3}],"steps":["Blend the oats, half the banana and eggs to form a thick batter.","Brush a non-stick pan with the measured oil. Cook small pancakes over medium-low heat for 2–3 minutes per side, until set.","Serve with the yogurt and remaining sliced banana."],"steps_ar":["اخلط الشوفان ونصف الموز والبيض للحصول على عجينة سميكة.","ادهن مقلاة غير لاصقة بالزيت المحدد واطه أقراصاً صغيرة ٢–٣ دقائق لكل جانب حتى تنضج.","قدمها مع الزبادي وبقية شرائح الموز."],"tags":["Vegetarian"],"allergens":["Egg","Gluten","Milk"],"image":"assets/recipes/02.webp","status":"published","version":1,"notes":"Quantities refer to the ingredient state listed. Nutrition is estimate