insert into public.panda_records(kind,id,data) values('nutrition_plans','studio_nutrition_dairy_free','{"id":"studio_nutrition_dairy_free","name":"Dairy-Free Meal Rotation","name_ar":"تنويع وجبات دون ألبان","status":"draft","version":1,"versions":[],"origin":"Panda Kitchen coach template · 2026-09-14","description":"Recipes selected without dairy ingredients. Check exact products and cross-contact if allergy is relevant.","description_ar":"وصفات مختارة دون مكونات ألبان. راجع المنتجات الفعلية والتلامس العرضي عند وجود حساسية.","notes":"Recipes selected without dairy ingredients. Check exact products and cross-contact if allergy is relevant. Template portions and the 2.5 L fluid placeholder require individual review. Targets initially match Menu 1; Menu 2 has its own calculated totals. Check allergies, preparation state and product labels. Adjust servings, targets and timing before publishing. Recipe amounts are estimates, not a clinical prescription.","notes_ar":"وصفات مختارة دون مكونات ألبان. راجع المنتجات الفعلية والتلامس العرضي عند وجود حساسية. تحتاج حصص القالب والقيمة الأولية للسوائل 2.5 لتر إلى مراجعة فردية. تطابق الأهداف القائمة الأولى مبدئياً، وللقائمة الثانية إجمالياتها المحسوبة. راجع الحساسية وحالة التحضير وملصقات المنتجات. عدّل الحصص والأهداف والتوقيت قبل النشر. الكميات تقديرية وليست وصفة سريرية.","targets":{"protein":161.5,"carbs":210.1,"fat":75.8,"fiber":45.4,"calories":2169,"water":2.5},"variants":[{"id":"day-1","name":"Menu 1","meals":[{"id":"meal_5","name":"Avocado egg toast","name_ar":"توست الأفوكادو والبيض","time":"07:30","instructions":"Hard-boil the eggs, then peel and halve. Toast the bread.\n\nMash the avocado with the lemon juice and spread over the toast.\n\nAdd the eggs and tomatoes. Use black pepper to taste.","instructions_ar":"اسلق البيض حتى يتماسك ثم قشره واقطعه وحمص الخبز.\n\nاهرس الأفوكادو مع عصير الليمون ووزعه على الخبز.\n\nأضف البيض والطماطم والفلفل الأسود حسب الرغبة.","items":[{"food_id":"ingredient_bread","quantity":100.0},{"food_id":